# dsmuser.sh - DSM local accounts for EAP-MSCHAPv2.
#
# Every local account's NT hash (MD4 of the password) lives in the SMB
# password store, /etc/samba/private/smbpasswd - the file smbd itself
# authenticates against. strongSwan's swanctl.conf 'ntlm' secret type takes
# that NT hash directly, so DSM accounts can log in over IKEv2/EAP-MSCHAPv2
# using their existing DSM password.
#
# DSM also exports the same hashes to /usr/syno/etc/synosmbpasswd.conf, but
# that copy is regenerated by DSM's own tooling and the hash written under an
# account there is not reliably that account's - which registered the wrong
# credential and made correct passwords fail. Read the store, not the export.

SMBPASSWD_FILE="/etc/samba/private/smbpasswd"
SYNOUSER_BIN="/usr/syno/sbin/synouser"
# NT hash of an empty password - accounts left at this value have no
# password set (e.g. DSM's disabled default admin); never register them.
EMPTY_NT_HASH="31D6CFE0D16AE931B73C59D7E0C089C0"

# pdbedit reads whatever passdb backend smb.conf selects, so it is the
# fallback for a DSM that does not use the plain smbpasswd backend. It ships
# inside the SMBService package rather than on the base system.
find_pdbedit() {
    for _p in /var/packages/SMBService/target/usr/bin/pdbedit \
              /usr/bin/pdbedit /usr/sbin/pdbedit; do
        [ -x "$_p" ] && { printf '%s\n' "$_p"; return 0; }
    done
    return 1
}

# Emit "name<TAB>NThash" for every account in the SMB password store.
# smbpasswd records are fixed-field:
#   name:uid:LM hash:NT hash:[account flags]:LCT-<hex>:
# so the account name is field 1 and its NT hash is field 4. pdbedit -L -w
# prints the same format, which is why one parse covers both sources.
dsm_nt_hashes() {
    if [ -r "$SMBPASSWD_FILE" ]; then
        awk -F: 'NF>=4 && $1 !~ /^#/ && $1 != "" {print $1"\t"$4}' "$SMBPASSWD_FILE"
        return 0
    fi
    _pdb=$(find_pdbedit) || return 1
    "$_pdb" -L -w 2>/dev/null | awk -F: 'NF>=4 && $1 !~ /^#/ && $1 != "" {print $1"\t"$4}'
}

# an NT hash is exactly 32 hex digits; anything else (an "NO PASSWORD"
# placeholder, a truncated record) is not a credential
valid_nt_hash() {
    case "$1" in
        ""|*[!0-9A-Fa-f]*) return 1 ;;
    esac
    [ "${#1}" = "32" ]
}

# NT hash for one account out of a "name<TAB>hash" list, upper-cased.
# Matched case-insensitively: DSM login names are unique regardless of case.
nt_hash_for() {
    printf '%s\n' "$2" | awk -F'\t' -v u="$1" 'tolower($1)==tolower(u) {print toupper($2); exit}'
}

# true if a DSM account may use the VPN. With no allowlist file, every account
# is allowed (the caller's own empty/expired filters still exclude unusable
# ones); once the Privileges page has been applied, only listed names pass.
dsm_user_allowed() {
    [ -f "$VPNUSERS" ] || return 0
    grep -qxF "$1" "$VPNUSERS"
}

# Emit swanctl 'ntlm' secret blocks for the active DSM accounts, read fresh
# from the SMB password store every time the config is rendered (i.e. every
# service start / apply), so new accounts and password changes are picked up.
#
# The real DSM login name (correct case, which is what the client sends as its
# EAP identity) comes from /etc/passwd (uid >= 1024). We iterate the real
# accounts and skip any that has no hash, has the empty-password hash, or is
# expired/disabled in DSM.
dsm_ntlm_secrets() {
    HASHES=$(dsm_nt_hashes)
    [ -n "$HASHES" ] || { log "WARN: no readable SMB password store - no DSM accounts registered"; return 0; }
    awk -F: '$3>=1024 && $3<60000 {print $1}' /etc/passwd 2>/dev/null | while read -r U; do
        [ -n "$U" ] || continue
        dsm_user_allowed "$U" || continue
        HUP=$(nt_hash_for "$U" "$HASHES")
        valid_nt_hash "$HUP" || continue
        [ "$HUP" = "$EMPTY_NT_HASH" ] && continue
        if [ -x "$SYNOUSER_BIN" ]; then
            "$SYNOUSER_BIN" --get "$U" 2>/dev/null | grep -qi 'Expired *: *\[true\]' && continue
        fi
        UESC=$(printf '%s' "$U" | sed 's/"/\\"/g')
        printf '    ntlm-%s {\n        id = "%s"\n        secret = 0x%s\n    }\n' "$U" "$UESC" "$HUP"
    done
}

# List every DSM local account for the Privileges page, one
# "name|status|allowed" line each:
#   status  = normal  (has a real password, not expired/disabled)
#           | disabled (no NT hash, empty-password hash, or expired in DSM)
#   allowed = yes|no   membership in the VPN allowlist; with no allowlist file
#                      yet, normal accounts default to yes, disabled to no.
dsm_users_list() {
    HASHES=$(dsm_nt_hashes)
    [ -n "$HASHES" ] || return 0
    awk -F: '$3>=1024 && $3<60000 {print $1}' /etc/passwd 2>/dev/null | while read -r U; do
        [ -n "$U" ] || continue
        HUP=$(nt_hash_for "$U" "$HASHES")
        ST="normal"
        if ! valid_nt_hash "$HUP" || [ "$HUP" = "$EMPTY_NT_HASH" ]; then
            ST="disabled"
        elif [ -x "$SYNOUSER_BIN" ] && "$SYNOUSER_BIN" --get "$U" 2>/dev/null | grep -qi 'Expired *: *\[true\]'; then
            ST="disabled"
        fi
        if [ -f "$VPNUSERS" ]; then
            if grep -qxF "$U" "$VPNUSERS"; then A="yes"; else A="no"; fi
        else
            [ "$ST" = "normal" ] && A="yes" || A="no"
        fi
        printf '%s|%s|%s\n' "$U" "$ST" "$A"
    done
}
